using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
            query = query.Where(s => s.Status == status);

        if (!string.IsNullOrEmpty(searchTerm))
            query = query.Where(s =>
                s.TrackingNumber.Contains(searchTerm) ||
                s.Destination.Contains(searchTerm) ||
                s.RecipientName.Contains(searchTerm) ||
                s.SenderName.Contains(searchTerm));

        return await query.OrderByDescending(s => s.CreatedAt).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
    {
        return await db.Shipments.FindAsync(id);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = GenerateTrackingNumber();
        shipment.CreatedAt = DateTime.UtcNow;
        shipment.Status = ShipmentStatus.Pending;

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var existing = await db.Shipments.FindAsync(shipment.Id)
            ?? throw new InvalidOperationException("Shipment not found.");

        existing.Status = shipment.Status;
        existing.Destination = shipment.Destination;
        existing.Origin = shipment.Origin;
        existing.EstimatedDelivery = shipment.EstimatedDelivery;
        existing.ActualDelivery = shipment.ActualDelivery;
        existing.RecipientName = shipment.RecipientName;
        existing.SenderName = shipment.SenderName;
        existing.Notes = shipment.Notes;

        if (shipment.Status == ShipmentStatus.Delivered && existing.ActualDelivery is null)
            existing.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return existing;
    }

    private static string GenerateTrackingNumber()
    {
        return $"ST-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpperInvariant()}";
    }
}

